    "gangtok": "gangtok",
    "\u092A\u0947\u0932\u093F\u0902\u0917": "pelling",
    "pelling": "pelling",
    "\u0938\u093F\u091F\u094B\u0902\u0917": "sitong",
    "sittong": "sitong",
    "sitong": "sitong",
    "\u0932\u093E\u0935\u093E": "lava",
    "lava": "lava",
    "\u0930\u0935\u093E\u0902\u0917\u0932\u093E": "ravangla",
    "ravangla": "ravangla",
    "zuluk": "zuluk",
    "\u091C\u0941\u0932\u0941\u0915": "zuluk",
    "siliguri": "siliguri",
    "\u0938\u093F\u0932\u093F\u0917\u0941\u0921\u093C\u0940": "siliguri",
    "njp": "njp",
