        if (id && id !== standName) {
          delete standsObj[id];
        }
        standsObj[standName] = {
          latitude: Number(record.latitude) || 0,
          longitude: Number(record.longitude) || 0,
          elevation: Number(record.elevation) || 1800,
          district: record.district || "",
          state: record.state || ""
        };
